WITH flagged AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) > INTERVAL 30 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM transactions), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT DATE_TRUNC('MONTH', txn_time) AS activity_month, merchant, PERCENTILE_APPROX(amount, 0.9) AS amount_p90, PERCENTILE_APPROX(is_new_burst, ARRAY(0.25, 0.5, 0.75)) AS is_new_burst_quartiles, GROUPING(DATE_TRUNC('MONTH', txn_time)) AS grouping_level FROM sessionized GROUP BY GROUPING SETS ((DATE_TRUNC('MONTH', txn_time), merchant), (DATE_TRUNC('MONTH', txn_time)), ());
